package com.example.shipping;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;

@Component
public class ShippingRateClient {
    private final RestClient restClient;
    private final ObjectMapper objectMapper = new ObjectMapper();

    public ShippingRateClient(RestClient.Builder builder) {
        this.restClient = builder.baseUrl("https://rates.example.com").build();
    }

    public ShippingRate fetch(String zipCode) throws JsonProcessingException {
        String body = restClient.get()
                .uri("/v1/rates?zip={zip}", zipCode)
                .retrieve()
                .body(String.class);
        return objectMapper.readValue(body, ShippingRate.class);
    }
}

package com.example.shipping;

public record ShippingRate(String carrier, int amount, int days) {
}

